-- them (Life Insurance x2 pools, Health Insurance x2 pools). Run as one
-- transaction in the Supabase SQL Editor, "without RLS" mode.

-- === Life Insurance module ===

update public.lessons set position = position + 1000 where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619';
update public.lessons set title = 'Term Life Insurance', description = 'The three kinds of term life insurance and how their cost behaves over time.', duration = '10 min', content = '<p>Death benefit / face amount / life insurance proceed: is how much insurance you buy. Premium: is money the insured/client pays to the insurer for coverage units (benefit).</p><br><p>Life Insurance: there are 2 types: <strong>Temporary</strong> and <strong>Permanent</strong>.</p><br><p><strong>The First Type: Temporary</strong> — usually 1 year, or 5, 10, 20, 30, or 40 years term period.</p><br><ul><br><li>This policy is purely insurance protection — NO CASH VALUE created, NO SAVING, No Investment.</li><br><li>Benefit is paid only if the insured dies during the policy period (98% of all term policies never claim).</li><br><li>Lowest premium in the early years but will be most expensive later.</li><br></ul><br><p>There are 3 products:</p><br><ul><br><li><strong>Level Term</strong>: the face amount stays the same, or level, throughout the policy period.</li><br><li><strong>Increasing Term</strong>: face amount will go up with the inflation rate, usually at 5% a year — premium increases too.</li><br><li><strong>Decreasing Term</strong>: face amount will go down to 0 at the end of the policy period — premium stays the same. (Mortgage = outstanding debt on a home; this is why decreasing term is often used for mortgage protection.)</li><br></ul><br><figure><br><img src="assets/lessons/term-life-cost-by-gender.png" alt="Line chart showing the cost of term life insurance rising with age for both men and women, with women''s premiums consistently lower than men''s at every age from 25 to 60."><br><figcaption>Term life premiums rise sharply with age, and are consistently lower for women than men.</figcaption><br></figure><br><figure><br><img src="assets/lessons/term-life-premium-comparison.png" alt="Chart comparing premium structures for a $500,000 policy: Annually Renewable Term starts low but rises steeply with age, while 20-year and 30-year Level Premium Term stay flat."><br><figcaption>Annually Renewable Term starts cheap but climbs fast — Level Term trades a higher starting premium for a flat rate across the whole term.</figcaption><br></figure><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">Shirley has a $500,000 10-year non-renewable level term life policy. If she dies 15 years after the policy''s inception date, how much will her beneficiary receive?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Nothing</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) $100,000</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) $250,000</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) $500,000</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The policy was non-renewable and its 10-year term already ended 5 years earlier, so there''s no coverage in force — nothing is paid.</p><br></div><br><div class="lesson-quiz-item" data-correct="d"><br><p class="lesson-quiz-question">Krissa purchases a 10-year level term life insurance policy that has a death benefit of $200,000. Which of these statements is true?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) The policy automatically converts to whole life after the 10-year period</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) The face amount will remain constant and the premium will increase over the 10-year period</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) The premium will remain constant and the face amount will increase over the 10-year period</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) The face amount and premium will remain constant over the 10-year period</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>"Level" term means both the face amount and the premium stay the same for the entire term.</p><br></div><br><div class="lesson-quiz-item" data-correct="d"><br><p class="lesson-quiz-question">All of the following are true about term life insurance policies EXCEPT the</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) insured can choose the premium payment mode</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) insured must answer medical questions on the application</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) face amount is paid if the insured dies during the policy period</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) face amount is paid if the insured survives to the end of the policy period</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Term insurance only pays a benefit if the insured dies during the term. Surviving to the end pays nothing, since term has no cash value or maturity benefit.</p><br></div><br>', position = 1 where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Types of Life Insurance';
insert into public.lessons (id, module_id, title, description, duration, type, content, position)
select gen_random_uuid(), '929e50a4-5e94-4e93-8f07-fe94b93f0619', 'Permanent Life Insurance & Riders', 'Whole life, universal life variants, endowment insurance, tax treatment, and the common life insurance riders.', '15 min', 'text', '<p><strong>The Second Type: Permanent</strong> — which means coverage for your entire life. Policy will stop, or endow, when the client is 120 years old (Endowment at 120). The insurance company pays a death benefit which will be equal to the cash value. It has CASH VALUE/SAVING — the client can loan money out without paying tax.</p><p><strong>Endowment insurance</strong> is a related product: it pays the full face amount if the insured survives to a stated date (the endowment date), or pays the death benefit if the insured dies before that date. Whole life is essentially an endowment at age 120, but a dedicated endowment policy can also be written to mature at an earlier stated age or after a set number of years.</p><br><p>There are 2 permanent products:</p><br><ul><br><li><strong>Whole life</strong> (original life or Traditional life) — Premium and Face amount are FIXED.</li><br><li><strong>Universal life</strong> — The Premium is FLEXIBLE (you can pay more or you can pay less), and the face amount is flexible too (you can increase or decrease it).</li><br></ul><br><p>There are 3 ways to earn interest on Universal life:</p><br><ul><br><li><strong>Fixed Universal life</strong>: the policy earns a fixed interest rate.</li><br><li><strong>Variable Universal life</strong>: the policy cash value goes to invest directly in the stock market, or in a separate / different sub-account. The value fluctuates — you may gain a lot but also lose a lot.</li><br><li><strong>Index Universal life</strong>: about 80% to 90% of the cash value stays in the general account, about 10-20% goes to invest. There is a Guaranteed rate and a Cap rate.</li><br></ul><p>Selling <strong>Variable Universal life</strong> (or any product funded through a variable/securities-based sub-account) requires a securities license in addition to the life insurance license, since the cash value is invested directly in the market.</p><br><p>Benefits of life insurance with cash value: Tax free Death Benefit (exempt from tax), Tax Deferred growth, Tax free loan/withdraw. In 1988 the IRS came out with a formula called the <strong>7 pay test</strong>. If the client fails or violates the 7 pay test (pays too much money into the policy), the IRS calls this a <strong>Modified Endowment Contract (MEC)</strong>. When a policy violates the 7 pay test, it is considered an INVESTMENT vehicle: it loses the tax benefit, and there''s a 10% penalty if withdrawn before age 59½. Pre-death distribution also needs to pay income tax / is taxable.</p><br><p><strong>Life Insurance Riders</strong> — Endorsements/optional features. If you want to buy one, you need to buy it at the beginning. They are optional features clients can pay extra money to add to their policy — this extra money is the cost for adding a rider, and it will not affect the cash value. There are about 6 to 7 of these:</p><br><ul><br><li><strong>Guaranteed Insurability</strong> — allows the client to purchase additional coverage without proof of insurability (no medical underwriting is required).</li><br><li><strong>Accidental Death</strong> — the insurance company will pay additional coverage (usually double or triple the original face amount) when the insured dies of an accident.</li><br><li><strong>Waiver of premium</strong> — the insurance company waives the premium when the person becomes totally or permanently disabled; you don''t have to pay any more premium. The policy is still in force / still active (usually until 65 years old, then the policy will lapse). The cash value continues to grow as if the insured is paying the premium — not affected.</li><br><li><strong>Payor of Benefit</strong> — only available in a Juvenile policy (parents or grandparents buy for their children). If the payor dies or becomes disabled, the child does not need to pay premium until they turn 21 or 25 years old.</li><br><li><strong>Cost of Living</strong> — inflation reduces money''s value; this rider increases the face amount with the inflation rate. Premium will also increase.</li><br><li><strong>Accelerated Death benefit</strong> (or Living benefit) — allows the client to get the death benefit before/prior to dying, because of terminal illness with about 6 to 12 months left to live. This rider is free.</li><br><li><strong>Automatic loan provision</strong> — uses the cash value to make the premium payment so the policy does not lapse.</li><br><li><strong>Family Term</strong> (children term rider) — allows the parents to add kids into their existing policy.</li><br></ul><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">Which type of permanent life insurance policy has both a flexible premium and a flexible face amount?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Whole life</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Universal life</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Level term</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Endowment</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Whole life fixes both the premium and face amount. Universal life is the one that lets the policyowner flex both.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">A policyowner pays too much into a cash-value life insurance policy and fails the 7-pay test. The policy is now classified as a</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Qualified plan</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Modified Endowment Contract (MEC)</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Variable annuity</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Nonforfeiture option</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Failing the 7-pay test reclassifies the policy as a MEC, which loses its usual tax advantages and is treated as an investment vehicle.</p><br></div><br><div class="lesson-quiz-item" data-correct="c"><br><p class="lesson-quiz-question">Which life insurance rider allows the insured to purchase additional coverage without proof of insurability?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Waiver of Premium</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Accidental Death</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Guaranteed Insurability</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Cost of Living</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The Guaranteed Insurability rider lets the client buy more coverage later without new medical underwriting.</p><br></div><br>', 2
where not exists (select 1 from public.lessons where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Permanent Life Insurance & Riders');
update public.lessons set position = 3 where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Business and Estate Uses of Life Insurance';
update public.lessons set title = 'Beneficiaries, Settlement Options & Nonforfeiture', description = 'The five ways a death benefit can be paid out, primary vs. contingent and revocable vs. irrevocable beneficiaries, and the three nonforfeiture options.', duration = '13 min', content = '<p><strong>Settlement options</strong> — 5 different ways an insurance company pays the death benefit to the beneficiaries when the insured dies. Death benefit money is NOT taxable / exempt from tax.</p><br><ul><br><li><strong>Lump Sum</strong>: company makes a one-time cash/check payment. This is the automatic/default option if no other choice is selected.</li><br><li><strong>Interest</strong>: the insurance company keeps the whole money for now and invests it. They pay earnings on the investment''s interest — this amount needs to pay tax. They will return all of the original death benefit when the beneficiary asks.</li><br><li><strong>Fixed period</strong>: the insured/client chooses how many years the company will make payments. Example: a $100k policy paid out over 10 years — year 1: $10k; year 2: $10k + some interest (taxable).</li><br><li><strong>Fixed amount</strong>: the insured/client chooses how much money the company pays out each year. Example: a $100k policy paid out at $20,000 a year — year 1: $20,000; year 2: $20,000 + some interest (taxable).</li><br><li><strong>Life income</strong>: the beneficiary uses the money to buy an annuity to get money for their lifetime — the company keeps the whole money forever and pays the beneficiary forever. <strong>Single life</strong>: pays on a single person''s life (total is most likely less compared to joint and survivor, so they pay a greater amount now). <strong>Joint and survivor</strong>: pays on 2 people''s lives (example: $1 million paying 1 person = 5%, $20k/month; $1 million paying 2 people = 4.5%, $19k/month).</li><br></ul><br><p>Beneficiary layers — there are 2 main layers:</p><br><ul><br><li><strong>Primary beneficiaries</strong>: are the 1st people who will get the death benefit.</li><br><li><strong>Contingent beneficiaries</strong>: are the secondary people who only get money when there are no primary beneficiaries.</li><br></ul><br><p>And there are 2 types of beneficiaries:</p><br><ul><br><li><strong>Revocable beneficiary</strong>: the client/insured can change to a different beneficiary at any time.</li><br><li><strong>Irrevocable beneficiary</strong>: is another owner of the policy — this person cannot be changed without their permission.</li><br></ul><br><p><strong>Non-Forfeiture Options</strong> — no-lose-cash-value options. When the insured/policyholder stops paying the premium and does not want to lose the cash value, they have 3 options to use the cash value:</p><br><ul><br><li><strong>Surrender / Cash out</strong>: cancel the policy and withdraw the cash value. The cost recovery basis (the money that you paid in) is tax exempt / no tax.</li><br><li><strong>Reduced Paid-Up</strong>: use the cash value to buy a smaller whole life. Note: (a) new whole life face amount is LESS than the original, (b) there is still cash value, (c) coverage is for life time.</li><br><li><strong>Extended Term</strong>: use the cash value to buy a term life policy. Note: term face amount/death benefit amount is the SAME as the original policy, but there is no cash value.</li><br></ul><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">A $50K whole life policy with a cash value of $10K has been in force for eleven years. The policyowner is unable to continue the premium payments. Which of the following describes the reduced paid-up nonforfeiture option?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) the cash value is used to select a $20K paid-up policy</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) the policy is surrendered and the policy owner is paid $10K by the insurer</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) the cash value is used to purchase a $50K term insurance policy that is paid up for ten years</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) the policyowner begins to receive monthly payments of $200 from the insurer that will continue for life</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Reduced paid-up uses the existing cash value as a single premium to buy a smaller, fully paid-up whole life policy — smaller than the original $50K face amount.</p><br></div><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">Which situation accurately describes a reduced paid-up nonforfeiture option?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Policy has a decreased face amount</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Face amount of the new policy equals that of the original policy</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Cash value is surrendered to policyowner</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Premiums must continue to be paid</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The new paid-up policy has a lower face amount than the original, since the existing cash value can only fund so much coverage as a single premium.</p><br></div><br><div class="lesson-quiz-item" data-correct="d"><br><p class="lesson-quiz-question">Dorian exercised a nonforfeiture option by using his life policy''s cash value to purchase an extended term insurance option. When the term insurance expires,</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) he has the option of resuming the original policy and paying the same premium</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) the coverage can be extended with a lump sum payment</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) all remaining cash values are paid to the policyowner</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) the protection ends</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Extended term coverage lasts only as long as the cash value can fund it. Once that term runs out, there''s no more coverage and no cash value left.</p><br></div><br>', position = 4 where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Life Insurance Policy Provisions';
insert into public.lessons (id, module_id, title, description, duration, type, content, position)
select gen_random_uuid(), '929e50a4-5e94-4e93-8f07-fe94b93f0619', 'Keeping a Policy in Force', 'Free-look and grace periods, lapse and reinstatement, the contestability period, and the five renewal types.', '12 min', 'text', '<p><strong>Policy provisions/clauses/rules:</strong></p><br><ul><br><li><strong>Free-look period</strong> (= Right-to-Exam = free cancelling period): allows the first 10-30 days to return the policy with a full refund; if returned after, a charge applies. Under 60 years old: allows 10-30 days. 60 and over: allows (for sure) 30 days.</li><br><li><strong>Grace period</strong>: is the period that allows the insured to pay an overdue payment. Group: given 31 days. Individual: given 30 days. If the insured dies within this time, the company will pay the full amount, but will subtract the missing premium and any outstanding loan, if any.</li><br></ul><br><p>After the grace period, if the client still does not pay, it depends on what policy he has. If he has a <strong>Term</strong> policy (no cash value), the policy will lapse/cancel. If he has a <strong>Permanent</strong> policy (has cash value), the <strong>Automatic Loan Provision</strong> will loan money from savings to pay the premium for you. After the Automatic Loan Provision period, the policy will lapse; if you want to continue coverage with the same policy, the client needs to be <strong>Reinstated</strong> or reopened. To reinstate, he needs to: pay all missed premiums, and provide insurability interest (redo blood test).</p><p>Policy loans taken against the cash value are also capped by law — the interest rate an insurer can charge on the loan cannot exceed the maximum rate set for the policy''s state of issue.</p><br><p><strong>Contestability period</strong>: the company CAN contest, challenge, or investigate. In the first 2 years, if the insured lied and dies, the company may investigate and deny the claim. <strong>Incontestability period</strong>: after 2 years, the insurer CANNOT deny the claim.</p><br><p><strong>Renewal types</strong> (renew = requesting to continue coverage):</p><br><ul><br><li><strong>Noncancellable</strong> — the best method. Company will allow you to renew, and may never raise the premium (cannot change the premium, cannot change anything in the policy).</li><br><li><strong>(Guaranteed) Renewable</strong> — company will allow you to renew, but the premium will increase / rate can change.</li><br><li><strong>Optionally Renewable</strong> — company can terminate/cancel when the contract comes to the end, so it may be renewed or may not.</li><br><li><strong>Conditionally Renewable</strong> — insurance company can renew your policy, but with conditions.</li><br><li><strong>Cancelable</strong> — can cancel any time.</li><br></ul><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">During the free-look period, an insured who returns the policy is entitled to</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) A full refund of premium paid</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Half of the premium paid</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) The cash value only</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Nothing</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The whole point of the free-look period is a full refund — the insured hasn''t committed to the policy yet.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">A policyowner with a cash-value life insurance policy misses a premium payment past the grace period. Under the Automatic Loan Provision, what happens?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) The policy is immediately cancelled with no recourse</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) The insurer loans money from the policy''s own cash value to cover the missed premium</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) The death benefit is permanently reduced by half</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) The policy automatically converts to term insurance</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The Automatic Loan Provision keeps the policy in force by borrowing the missed premium against the policy''s own cash value.</p><br></div><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">Which renewal type gives the insurer the least ability to change the contract — the company can never raise the premium or alter the policy?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Noncancellable</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Guaranteed Renewable</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Optionally Renewable</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Conditionally Renewable</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Noncancellable is the strongest protection for the insured — the insurer can never raise the premium or change the policy.</p><br></div><br>', 5
where not exists (select 1 from public.lessons where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Keeping a Policy in Force');
update public.lessons set position = 6 where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Participating vs. Non-Participating Insurers';
update public.lessons set position = 7 where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Underwriting and Group Life Insurance';
update public.lessons set title = 'Retirement Plans', description = 'Qualified vs. non-qualified retirement plans and the ERISA, 59\x{bd}, and 70\x{bd} rules that govern them.', duration = '13 min', content = '<p><strong>Retirement plans</strong> (401k, 403B, IRA, Roth 401k, Roth IRA...). You need to pay tax now (contribution) or you can pay later (distribution).</p><br><p><strong>Qualified plan</strong> = Pay Tax later. Allowed by the IRS to deduct the contribution from that year''s income tax. Example: you make $60K - $5K (contribution) = $55K income. Such as: 401k, IRA, 403B, or Tax Shelter Annuity (TSA). Pros: contribution is tax deductible. Cons: distribution / withdrawal is taxable.</p><p>Other examples of qualified plans include the <strong>SIMPLE Plan</strong> and the <strong>Keogh Plan</strong> (for self-employed individuals) — both allow tax-deductible contributions, unlike a Roth IRA, which does not qualify for a federal income tax deduction.</p><br><p><strong>Non-Qualified plan</strong> = Pay Tax Now. Not allowed to deduct the contribution from that year''s income tax. Example: you make $60K - $5K = $60K income (no deduction). Such as: Roth IRA, Roth 401k, Life Insurance, 529 plan. Contribution is not deductible, but withdrawal / distribution is tax free.</p><br><p><strong>ERISA</strong> (a government law) requires companies to disclose and report fees and costs. Restrictions: <strong>Nondiscrimination</strong> — cannot favor highly earned employees. Follow the <strong>59½ rule</strong>: if you withdraw before this age, there will be a 10% tax penalty. Exemptions: first time home buyer, death of insured, qualified college tuition. Follow the <strong>70½ rule (RMD: Required Minimum Distribution)</strong> — when you turn this age, you have to withdraw a certain amount, or pay a 50% tax penalty on the amount you were supposed to take out. Note: now it''s age 72 for RMD.</p><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">Retirement plans cannot favor highly compensated employs. The government regulation that prevents this from happening is called</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Defamation b</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Nondiscrimination</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) IRC Section 457</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) HR-10</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Nondiscrimination rules require qualified retirement plans to benefit employees broadly, not just those who are highly compensated.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">Which of the following retirement plans is a QUALIFIED plan, meaning the contribution is tax deductible?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Roth IRA</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) 401k</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Roth 401k</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Life insurance</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>A 401k is a qualified plan — the contribution is deductible now, and distributions are taxed later. The other three are non-qualified: taxed now, tax-free later.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">Under the 59½ rule, withdrawing qualified retirement funds before that age (with no exemption applying) results in what penalty?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) 5% tax penalty</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) 10% tax penalty</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) 50% tax penalty</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) No penalty</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>An early withdrawal before age 59½ triggers a 10% tax penalty, unless an exemption like a first-time home purchase applies.</p><br></div><br>', position = 8 where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Retirement Plans and Annuities';
insert into public.lessons (id, module_id, title, description, duration, type, content, position)
select gen_random_uuid(), '929e50a4-5e94-4e93-8f07-fe94b93f0619', 'Annuities', 'How annuities work, deferred vs. immediate annuities, payout options, the parties to an annuity contract, and suitability requirements.', '12 min', 'text', '<p><strong>Annuity</strong>: a product / retirement account which systematically liquidates a sum of money. It''s provided by an insurance company, and is the opposite of life insurance (which creates a sum of money / estate). Who buys an annuity: those who are afraid of living longer than their financial resources.</p><br><p>There are 2 types: <strong>Deferred</strong> (delay withdrawing benefit 12 months later or more — only a deferred annuity has an accumulation period / growth, with 3 methods of gaining interest: Variable, Fixed, Index) and <strong>Immediate</strong>.</p><br><p>Annuity options — distribution methods, different ways the annuitant receives the benefit:</p><br><ul><br><li><strong>Straight life / Life income</strong>: as long as you live they pay; when you die, they stop paying. Therefore, NO BENEFICIARY.</li><br><li><strong>Period Certain</strong>: guaranteed minimum for whatever time you choose, and continues to pay until you die, maximum your lifetime. Has a beneficiary.</li><br><li><strong>Joint and survivor annuity</strong>: insurance company pays benefit based on two people''s lives.</li><br></ul><br><p>There are 4 entities (people) in an annuity:</p><br><ul><br><li><strong>Payor</strong>: is the person who pays the money into the policy.</li><br><li><strong>Annuitant</strong>: is the elderly person who receives money yearly.</li><br><li><strong>Policyowner</strong>: is the person with the most power — to cancel or surrender.</li><br><li><strong>Beneficiary</strong>: is the person who will get money when the annuitant dies.</li><br></ul><p>Before recommending an annuity, the producer must gather <strong>suitability information</strong> from the client — including age, annual income, financial situation, and financial experience/objectives — to make sure the product is appropriate for that client.</p><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="c"><br><p class="lesson-quiz-question">People commonly purchase an annuity to protect against the risk of</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) dying too soon</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) becoming insurable</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) outliving their financial resources</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) dying before their home mortgage is paid off</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>An annuity''s core purpose is to guarantee income for life, protecting against the risk of outliving your savings.</p><br></div><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">An immediate annuity has been purchased with a single premium. When does the annuitant typically begin receiving benefit payments?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) 1 month</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) 6 months</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) 12 months</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) 24 months</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>By definition, an "immediate" annuity starts paying out right away — typically within about one payment interval of purchase, unlike a deferred annuity.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">In a Joint and Survivor annuity option, the payout is based on</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) A single life</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Two people''s lives</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) The policyowner''s life only, regardless of the annuitant</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) The beneficiary''s age at the time of the annuitant''s death</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Joint and Survivor pays out based on two people''s lives, continuing as long as either one is alive.</p><br></div><br>', 9
where not exists (select 1 from public.lessons where module_id = '929e50a4-5e94-4e93-8f07-fe94b93f0619' and title = 'Annuities');

update public.lessons set position = position + 1000 where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab';
update public.lessons set title = 'Term Life Insurance', description = 'The three kinds of term life insurance and how their cost behaves over time.', duration = '10 min', content = '<p>Death benefit / face amount / life insurance proceed: is how much insurance you buy. Premium: is money the insured/client pays to the insurer for coverage units (benefit).</p><br><p>Life Insurance: there are 2 types: <strong>Temporary</strong> and <strong>Permanent</strong>.</p><br><p><strong>The First Type: Temporary</strong> — usually 1 year, or 5, 10, 20, 30, or 40 years term period.</p><br><ul><br><li>This policy is purely insurance protection — NO CASH VALUE created, NO SAVING, No Investment.</li><br><li>Benefit is paid only if the insured dies during the policy period (98% of all term policies never claim).</li><br><li>Lowest premium in the early years but will be most expensive later.</li><br></ul><br><p>There are 3 products:</p><br><ul><br><li><strong>Level Term</strong>: the face amount stays the same, or level, throughout the policy period.</li><br><li><strong>Increasing Term</strong>: face amount will go up with the inflation rate, usually at 5% a year — premium increases too.</li><br><li><strong>Decreasing Term</strong>: face amount will go down to 0 at the end of the policy period — premium stays the same. (Mortgage = outstanding debt on a home; this is why decreasing term is often used for mortgage protection.)</li><br></ul><br><figure><br><img src="assets/lessons/term-life-cost-by-gender.png" alt="Line chart showing the cost of term life insurance rising with age for both men and women, with women''s premiums consistently lower than men''s at every age from 25 to 60."><br><figcaption>Term life premiums rise sharply with age, and are consistently lower for women than men.</figcaption><br></figure><br><figure><br><img src="assets/lessons/term-life-premium-comparison.png" alt="Chart comparing premium structures for a $500,000 policy: Annually Renewable Term starts low but rises steeply with age, while 20-year and 30-year Level Premium Term stay flat."><br><figcaption>Annually Renewable Term starts cheap but climbs fast — Level Term trades a higher starting premium for a flat rate across the whole term.</figcaption><br></figure><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">Shirley has a $500,000 10-year non-renewable level term life policy. If she dies 15 years after the policy''s inception date, how much will her beneficiary receive?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Nothing</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) $100,000</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) $250,000</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) $500,000</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The policy was non-renewable and its 10-year term already ended 5 years earlier, so there''s no coverage in force — nothing is paid.</p><br></div><br><div class="lesson-quiz-item" data-correct="d"><br><p class="lesson-quiz-question">Krissa purchases a 10-year level term life insurance policy that has a death benefit of $200,000. Which of these statements is true?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) The policy automatically converts to whole life after the 10-year period</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) The face amount will remain constant and the premium will increase over the 10-year period</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) The premium will remain constant and the face amount will increase over the 10-year period</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) The face amount and premium will remain constant over the 10-year period</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>"Level" term means both the face amount and the premium stay the same for the entire term.</p><br></div><br><div class="lesson-quiz-item" data-correct="d"><br><p class="lesson-quiz-question">All of the following are true about term life insurance policies EXCEPT the</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) insured can choose the premium payment mode</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) insured must answer medical questions on the application</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) face amount is paid if the insured dies during the policy period</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) face amount is paid if the insured survives to the end of the policy period</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Term insurance only pays a benefit if the insured dies during the term. Surviving to the end pays nothing, since term has no cash value or maturity benefit.</p><br></div><br>', position = 1 where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Types of Life Insurance';
insert into public.lessons (id, module_id, title, description, duration, type, content, position)
select gen_random_uuid(), 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab', 'Permanent Life Insurance & Riders', 'Whole life, universal life variants, endowment insurance, tax treatment, and the common life insurance riders.', '15 min', 'text', '<p><strong>The Second Type: Permanent</strong> — which means coverage for your entire life. Policy will stop, or endow, when the client is 120 years old (Endowment at 120). The insurance company pays a death benefit which will be equal to the cash value. It has CASH VALUE/SAVING — the client can loan money out without paying tax.</p><p><strong>Endowment insurance</strong> is a related product: it pays the full face amount if the insured survives to a stated date (the endowment date), or pays the death benefit if the insured dies before that date. Whole life is essentially an endowment at age 120, but a dedicated endowment policy can also be written to mature at an earlier stated age or after a set number of years.</p><br><p>There are 2 permanent products:</p><br><ul><br><li><strong>Whole life</strong> (original life or Traditional life) — Premium and Face amount are FIXED.</li><br><li><strong>Universal life</strong> — The Premium is FLEXIBLE (you can pay more or you can pay less), and the face amount is flexible too (you can increase or decrease it).</li><br></ul><br><p>There are 3 ways to earn interest on Universal life:</p><br><ul><br><li><strong>Fixed Universal life</strong>: the policy earns a fixed interest rate.</li><br><li><strong>Variable Universal life</strong>: the policy cash value goes to invest directly in the stock market, or in a separate / different sub-account. The value fluctuates — you may gain a lot but also lose a lot.</li><br><li><strong>Index Universal life</strong>: about 80% to 90% of the cash value stays in the general account, about 10-20% goes to invest. There is a Guaranteed rate and a Cap rate.</li><br></ul><p>Selling <strong>Variable Universal life</strong> (or any product funded through a variable/securities-based sub-account) requires a securities license in addition to the life insurance license, since the cash value is invested directly in the market.</p><br><p>Benefits of life insurance with cash value: Tax free Death Benefit (exempt from tax), Tax Deferred growth, Tax free loan/withdraw. In 1988 the IRS came out with a formula called the <strong>7 pay test</strong>. If the client fails or violates the 7 pay test (pays too much money into the policy), the IRS calls this a <strong>Modified Endowment Contract (MEC)</strong>. When a policy violates the 7 pay test, it is considered an INVESTMENT vehicle: it loses the tax benefit, and there''s a 10% penalty if withdrawn before age 59½. Pre-death distribution also needs to pay income tax / is taxable.</p><br><p><strong>Life Insurance Riders</strong> — Endorsements/optional features. If you want to buy one, you need to buy it at the beginning. They are optional features clients can pay extra money to add to their policy — this extra money is the cost for adding a rider, and it will not affect the cash value. There are about 6 to 7 of these:</p><br><ul><br><li><strong>Guaranteed Insurability</strong> — allows the client to purchase additional coverage without proof of insurability (no medical underwriting is required).</li><br><li><strong>Accidental Death</strong> — the insurance company will pay additional coverage (usually double or triple the original face amount) when the insured dies of an accident.</li><br><li><strong>Waiver of premium</strong> — the insurance company waives the premium when the person becomes totally or permanently disabled; you don''t have to pay any more premium. The policy is still in force / still active (usually until 65 years old, then the policy will lapse). The cash value continues to grow as if the insured is paying the premium — not affected.</li><br><li><strong>Payor of Benefit</strong> — only available in a Juvenile policy (parents or grandparents buy for their children). If the payor dies or becomes disabled, the child does not need to pay premium until they turn 21 or 25 years old.</li><br><li><strong>Cost of Living</strong> — inflation reduces money''s value; this rider increases the face amount with the inflation rate. Premium will also increase.</li><br><li><strong>Accelerated Death benefit</strong> (or Living benefit) — allows the client to get the death benefit before/prior to dying, because of terminal illness with about 6 to 12 months left to live. This rider is free.</li><br><li><strong>Automatic loan provision</strong> — uses the cash value to make the premium payment so the policy does not lapse.</li><br><li><strong>Family Term</strong> (children term rider) — allows the parents to add kids into their existing policy.</li><br></ul><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">Which type of permanent life insurance policy has both a flexible premium and a flexible face amount?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Whole life</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Universal life</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Level term</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Endowment</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Whole life fixes both the premium and face amount. Universal life is the one that lets the policyowner flex both.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">A policyowner pays too much into a cash-value life insurance policy and fails the 7-pay test. The policy is now classified as a</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Qualified plan</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Modified Endowment Contract (MEC)</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Variable annuity</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Nonforfeiture option</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Failing the 7-pay test reclassifies the policy as a MEC, which loses its usual tax advantages and is treated as an investment vehicle.</p><br></div><br><div class="lesson-quiz-item" data-correct="c"><br><p class="lesson-quiz-question">Which life insurance rider allows the insured to purchase additional coverage without proof of insurability?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Waiver of Premium</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Accidental Death</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Guaranteed Insurability</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Cost of Living</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The Guaranteed Insurability rider lets the client buy more coverage later without new medical underwriting.</p><br></div><br>', 2
where not exists (select 1 from public.lessons where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Permanent Life Insurance & Riders');
update public.lessons set position = 3 where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Business and Estate Uses of Life Insurance';
update public.lessons set title = 'Beneficiaries, Settlement Options & Nonforfeiture', description = 'The five ways a death benefit can be paid out, primary vs. contingent and revocable vs. irrevocable beneficiaries, and the three nonforfeiture options.', duration = '13 min', content = '<p><strong>Settlement options</strong> — 5 different ways an insurance company pays the death benefit to the beneficiaries when the insured dies. Death benefit money is NOT taxable / exempt from tax.</p><br><ul><br><li><strong>Lump Sum</strong>: company makes a one-time cash/check payment. This is the automatic/default option if no other choice is selected.</li><br><li><strong>Interest</strong>: the insurance company keeps the whole money for now and invests it. They pay earnings on the investment''s interest — this amount needs to pay tax. They will return all of the original death benefit when the beneficiary asks.</li><br><li><strong>Fixed period</strong>: the insured/client chooses how many years the company will make payments. Example: a $100k policy paid out over 10 years — year 1: $10k; year 2: $10k + some interest (taxable).</li><br><li><strong>Fixed amount</strong>: the insured/client chooses how much money the company pays out each year. Example: a $100k policy paid out at $20,000 a year — year 1: $20,000; year 2: $20,000 + some interest (taxable).</li><br><li><strong>Life income</strong>: the beneficiary uses the money to buy an annuity to get money for their lifetime — the company keeps the whole money forever and pays the beneficiary forever. <strong>Single life</strong>: pays on a single person''s life (total is most likely less compared to joint and survivor, so they pay a greater amount now). <strong>Joint and survivor</strong>: pays on 2 people''s lives (example: $1 million paying 1 person = 5%, $20k/month; $1 million paying 2 people = 4.5%, $19k/month).</li><br></ul><br><p>Beneficiary layers — there are 2 main layers:</p><br><ul><br><li><strong>Primary beneficiaries</strong>: are the 1st people who will get the death benefit.</li><br><li><strong>Contingent beneficiaries</strong>: are the secondary people who only get money when there are no primary beneficiaries.</li><br></ul><br><p>And there are 2 types of beneficiaries:</p><br><ul><br><li><strong>Revocable beneficiary</strong>: the client/insured can change to a different beneficiary at any time.</li><br><li><strong>Irrevocable beneficiary</strong>: is another owner of the policy — this person cannot be changed without their permission.</li><br></ul><br><p><strong>Non-Forfeiture Options</strong> — no-lose-cash-value options. When the insured/policyholder stops paying the premium and does not want to lose the cash value, they have 3 options to use the cash value:</p><br><ul><br><li><strong>Surrender / Cash out</strong>: cancel the policy and withdraw the cash value. The cost recovery basis (the money that you paid in) is tax exempt / no tax.</li><br><li><strong>Reduced Paid-Up</strong>: use the cash value to buy a smaller whole life. Note: (a) new whole life face amount is LESS than the original, (b) there is still cash value, (c) coverage is for life time.</li><br><li><strong>Extended Term</strong>: use the cash value to buy a term life policy. Note: term face amount/death benefit amount is the SAME as the original policy, but there is no cash value.</li><br></ul><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">A $50K whole life policy with a cash value of $10K has been in force for eleven years. The policyowner is unable to continue the premium payments. Which of the following describes the reduced paid-up nonforfeiture option?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) the cash value is used to select a $20K paid-up policy</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) the policy is surrendered and the policy owner is paid $10K by the insurer</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) the cash value is used to purchase a $50K term insurance policy that is paid up for ten years</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) the policyowner begins to receive monthly payments of $200 from the insurer that will continue for life</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Reduced paid-up uses the existing cash value as a single premium to buy a smaller, fully paid-up whole life policy — smaller than the original $50K face amount.</p><br></div><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">Which situation accurately describes a reduced paid-up nonforfeiture option?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Policy has a decreased face amount</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Face amount of the new policy equals that of the original policy</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Cash value is surrendered to policyowner</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Premiums must continue to be paid</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The new paid-up policy has a lower face amount than the original, since the existing cash value can only fund so much coverage as a single premium.</p><br></div><br><div class="lesson-quiz-item" data-correct="d"><br><p class="lesson-quiz-question">Dorian exercised a nonforfeiture option by using his life policy''s cash value to purchase an extended term insurance option. When the term insurance expires,</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) he has the option of resuming the original policy and paying the same premium</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) the coverage can be extended with a lump sum payment</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) all remaining cash values are paid to the policyowner</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) the protection ends</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Extended term coverage lasts only as long as the cash value can fund it. Once that term runs out, there''s no more coverage and no cash value left.</p><br></div><br>', position = 4 where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Life Insurance Policy Provisions';
insert into public.lessons (id, module_id, title, description, duration, type, content, position)
select gen_random_uuid(), 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab', 'Keeping a Policy in Force', 'Free-look and grace periods, lapse and reinstatement, the contestability period, and the five renewal types.', '12 min', 'text', '<p><strong>Policy provisions/clauses/rules:</strong></p><br><ul><br><li><strong>Free-look period</strong> (= Right-to-Exam = free cancelling period): allows the first 10-30 days to return the policy with a full refund; if returned after, a charge applies. Under 60 years old: allows 10-30 days. 60 and over: allows (for sure) 30 days.</li><br><li><strong>Grace period</strong>: is the period that allows the insured to pay an overdue payment. Group: given 31 days. Individual: given 30 days. If the insured dies within this time, the company will pay the full amount, but will subtract the missing premium and any outstanding loan, if any.</li><br></ul><br><p>After the grace period, if the client still does not pay, it depends on what policy he has. If he has a <strong>Term</strong> policy (no cash value), the policy will lapse/cancel. If he has a <strong>Permanent</strong> policy (has cash value), the <strong>Automatic Loan Provision</strong> will loan money from savings to pay the premium for you. After the Automatic Loan Provision period, the policy will lapse; if you want to continue coverage with the same policy, the client needs to be <strong>Reinstated</strong> or reopened. To reinstate, he needs to: pay all missed premiums, and provide insurability interest (redo blood test).</p><p>Policy loans taken against the cash value are also capped by law — the interest rate an insurer can charge on the loan cannot exceed the maximum rate set for the policy''s state of issue.</p><br><p><strong>Contestability period</strong>: the company CAN contest, challenge, or investigate. In the first 2 years, if the insured lied and dies, the company may investigate and deny the claim. <strong>Incontestability period</strong>: after 2 years, the insurer CANNOT deny the claim.</p><br><p><strong>Renewal types</strong> (renew = requesting to continue coverage):</p><br><ul><br><li><strong>Noncancellable</strong> — the best method. Company will allow you to renew, and may never raise the premium (cannot change the premium, cannot change anything in the policy).</li><br><li><strong>(Guaranteed) Renewable</strong> — company will allow you to renew, but the premium will increase / rate can change.</li><br><li><strong>Optionally Renewable</strong> — company can terminate/cancel when the contract comes to the end, so it may be renewed or may not.</li><br><li><strong>Conditionally Renewable</strong> — insurance company can renew your policy, but with conditions.</li><br><li><strong>Cancelable</strong> — can cancel any time.</li><br></ul><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">During the free-look period, an insured who returns the policy is entitled to</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) A full refund of premium paid</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Half of the premium paid</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) The cash value only</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Nothing</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The whole point of the free-look period is a full refund — the insured hasn''t committed to the policy yet.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">A policyowner with a cash-value life insurance policy misses a premium payment past the grace period. Under the Automatic Loan Provision, what happens?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) The policy is immediately cancelled with no recourse</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) The insurer loans money from the policy''s own cash value to cover the missed premium</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) The death benefit is permanently reduced by half</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) The policy automatically converts to term insurance</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>The Automatic Loan Provision keeps the policy in force by borrowing the missed premium against the policy''s own cash value.</p><br></div><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">Which renewal type gives the insurer the least ability to change the contract — the company can never raise the premium or alter the policy?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Noncancellable</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Guaranteed Renewable</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Optionally Renewable</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Conditionally Renewable</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Noncancellable is the strongest protection for the insured — the insurer can never raise the premium or change the policy.</p><br></div><br>', 5
where not exists (select 1 from public.lessons where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Keeping a Policy in Force');
update public.lessons set position = 6 where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Participating vs. Non-Participating Insurers';
update public.lessons set position = 7 where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Underwriting and Group Life Insurance';
update public.lessons set title = 'Retirement Plans', description = 'Qualified vs. non-qualified retirement plans and the ERISA, 59\x{bd}, and 70\x{bd} rules that govern them.', duration = '13 min', content = '<p><strong>Retirement plans</strong> (401k, 403B, IRA, Roth 401k, Roth IRA...). You need to pay tax now (contribution) or you can pay later (distribution).</p><br><p><strong>Qualified plan</strong> = Pay Tax later. Allowed by the IRS to deduct the contribution from that year''s income tax. Example: you make $60K - $5K (contribution) = $55K income. Such as: 401k, IRA, 403B, or Tax Shelter Annuity (TSA). Pros: contribution is tax deductible. Cons: distribution / withdrawal is taxable.</p><p>Other examples of qualified plans include the <strong>SIMPLE Plan</strong> and the <strong>Keogh Plan</strong> (for self-employed individuals) — both allow tax-deductible contributions, unlike a Roth IRA, which does not qualify for a federal income tax deduction.</p><br><p><strong>Non-Qualified plan</strong> = Pay Tax Now. Not allowed to deduct the contribution from that year''s income tax. Example: you make $60K - $5K = $60K income (no deduction). Such as: Roth IRA, Roth 401k, Life Insurance, 529 plan. Contribution is not deductible, but withdrawal / distribution is tax free.</p><br><p><strong>ERISA</strong> (a government law) requires companies to disclose and report fees and costs. Restrictions: <strong>Nondiscrimination</strong> — cannot favor highly earned employees. Follow the <strong>59½ rule</strong>: if you withdraw before this age, there will be a 10% tax penalty. Exemptions: first time home buyer, death of insured, qualified college tuition. Follow the <strong>70½ rule (RMD: Required Minimum Distribution)</strong> — when you turn this age, you have to withdraw a certain amount, or pay a 50% tax penalty on the amount you were supposed to take out. Note: now it''s age 72 for RMD.</p><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">Retirement plans cannot favor highly compensated employs. The government regulation that prevents this from happening is called</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Defamation b</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Nondiscrimination</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) IRC Section 457</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) HR-10</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Nondiscrimination rules require qualified retirement plans to benefit employees broadly, not just those who are highly compensated.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">Which of the following retirement plans is a QUALIFIED plan, meaning the contribution is tax deductible?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) Roth IRA</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) 401k</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) Roth 401k</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) Life insurance</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>A 401k is a qualified plan — the contribution is deductible now, and distributions are taxed later. The other three are non-qualified: taxed now, tax-free later.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">Under the 59½ rule, withdrawing qualified retirement funds before that age (with no exemption applying) results in what penalty?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) 5% tax penalty</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) 10% tax penalty</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) 50% tax penalty</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) No penalty</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>An early withdrawal before age 59½ triggers a 10% tax penalty, unless an exemption like a first-time home purchase applies.</p><br></div><br>', position = 8 where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Retirement Plans and Annuities';
insert into public.lessons (id, module_id, title, description, duration, type, content, position)
select gen_random_uuid(), 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab', 'Annuities', 'How annuities work, deferred vs. immediate annuities, payout options, the parties to an annuity contract, and suitability requirements.', '12 min', 'text', '<p><strong>Annuity</strong>: a product / retirement account which systematically liquidates a sum of money. It''s provided by an insurance company, and is the opposite of life insurance (which creates a sum of money / estate). Who buys an annuity: those who are afraid of living longer than their financial resources.</p><br><p>There are 2 types: <strong>Deferred</strong> (delay withdrawing benefit 12 months later or more — only a deferred annuity has an accumulation period / growth, with 3 methods of gaining interest: Variable, Fixed, Index) and <strong>Immediate</strong>.</p><br><p>Annuity options — distribution methods, different ways the annuitant receives the benefit:</p><br><ul><br><li><strong>Straight life / Life income</strong>: as long as you live they pay; when you die, they stop paying. Therefore, NO BENEFICIARY.</li><br><li><strong>Period Certain</strong>: guaranteed minimum for whatever time you choose, and continues to pay until you die, maximum your lifetime. Has a beneficiary.</li><br><li><strong>Joint and survivor annuity</strong>: insurance company pays benefit based on two people''s lives.</li><br></ul><br><p>There are 4 entities (people) in an annuity:</p><br><ul><br><li><strong>Payor</strong>: is the person who pays the money into the policy.</li><br><li><strong>Annuitant</strong>: is the elderly person who receives money yearly.</li><br><li><strong>Policyowner</strong>: is the person with the most power — to cancel or surrender.</li><br><li><strong>Beneficiary</strong>: is the person who will get money when the annuitant dies.</li><br></ul><p>Before recommending an annuity, the producer must gather <strong>suitability information</strong> from the client — including age, annual income, financial situation, and financial experience/objectives — to make sure the product is appropriate for that client.</p><br><h3>Check Your Knowledge</h3><br><div class="lesson-quiz-item" data-correct="c"><br><p class="lesson-quiz-question">People commonly purchase an annuity to protect against the risk of</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) dying too soon</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) becoming insurable</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) outliving their financial resources</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) dying before their home mortgage is paid off</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>An annuity''s core purpose is to guarantee income for life, protecting against the risk of outliving your savings.</p><br></div><br><div class="lesson-quiz-item" data-correct="a"><br><p class="lesson-quiz-question">An immediate annuity has been purchased with a single premium. When does the annuitant typically begin receiving benefit payments?</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) 1 month</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) 6 months</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) 12 months</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) 24 months</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>By definition, an "immediate" annuity starts paying out right away — typically within about one payment interval of purchase, unlike a deferred annuity.</p><br></div><br><div class="lesson-quiz-item" data-correct="b"><br><p class="lesson-quiz-question">In a Joint and Survivor annuity option, the payout is based on</p><br><div class="lesson-quiz-options"><br><button type="button" class="lesson-quiz-option" data-letter="a">A) A single life</button><br><button type="button" class="lesson-quiz-option" data-letter="b">B) Two people''s lives</button><br><button type="button" class="lesson-quiz-option" data-letter="c">C) The policyowner''s life only, regardless of the annuitant</button><br><button type="button" class="lesson-quiz-option" data-letter="d">D) The beneficiary''s age at the time of the annuitant''s death</button><br></div><br><p class="lesson-quiz-feedback" hidden></p><br><p class="lesson-quiz-explanation" hidden>Joint and Survivor pays out based on two people''s lives, continuing as long as either one is alive.</p><br></div><br>', 9
where not exists (select 1 from public.lessons where module_id = 'dcc403da-41ac-4b2d-988a-ccce1d0a0dab' and title = 'Annuities');

